FUNCTION_BLOCK FB
VAR_INPUT
    openBtn    : BOOL;
    closeBtn   : BOOL;
    openLimit  : BOOL;
    closeLimit : BOOL;
    obstacle   : BOOL;
END_VAR
VAR_OUTPUT
    motorUp    : BOOL := FALSE;
    motorDown  : BOOL := FALSE;
    errorFlag  : BOOL := FALSE;
END_VAR
VAR
    curState     : INT := 0;
    prevOpenBtn  : BOOL := FALSE;
    prevCloseBtn : BOOL := FALSE;
END_VAR

CASE curState OF
    3: // FAULT
        IF openBtn AND closeBtn THEN
            curState  := 0;
            errorFlag := FALSE;
        END_IF

    1: // OPENING
        IF obstacle THEN
            curState  := 3;
            errorFlag := TRUE;
        ELSIF openLimit THEN
            curState := 0;
        END_IF

    2: // CLOSING
        IF obstacle THEN
            curState := 1;
        ELSIF closeLimit THEN
            curState := 0;
        END_IF

    0: // IDLE
        IF openBtn AND NOT prevOpenBtn AND NOT openLimit THEN
            curState := 1;
        ELSIF closeBtn AND NOT prevCloseBtn AND NOT closeLimit THEN
            curState := 2;
        END_IF
END_CASE

motorUp   := (curState = 1) AND NOT openLimit;
motorDown := (curState = 2) AND NOT obstacle;

prevOpenBtn  := openBtn;
prevCloseBtn := closeBtn;
END_FUNCTION_BLOCK
